<?php get_header(); $layout=get_theme_mod('md_archive_sidebar','right'); ?><main id="main" class="container md-magazine-layout <?php echo esc_attr($layout==='none'?'without-sidebar':'sidebar-'.$layout); ?>"><div class="md-magazine-main"><header class="md-magazine-intro"><span class="eyebrow">مجله / مروارید درون</span><h1><?php echo esc_html(md_theme_option('magazine_title','مجله مروارید درون')); ?></h1><p class="md-section-lead"><?php echo esc_html(md_theme_option('magazine_intro','داستان‌ها و مقاله‌هایی درباره ارتباط، خودشناسی و رشد والدین و نوجوانان.')); ?></p></header><?php echo md_pretty_search(); ?><div class="md-filter-bar"><?php foreach(get_categories(['number'=>10,'hide_empty'=>true]) as $cat){echo '<a class="md-academy-pill" href="'.esc_url(get_category_link($cat)).'">'.esc_html($cat->name).'</a>';} ?></div><div class="md-archive-cards card-grid"><?php if(have_posts()):while(have_posts()):the_post();md_card(get_the_ID());endwhile;else: ?><p>هنوز مطلبی منتشر نشده است.</p><?php endif; ?></div><div class="pagination"><?php the_posts_pagination(); ?></div></div><?php md_render_sidebar('magazine', $layout); ?></main><?php get_footer(); ?>